function calculateDiscount(cartItems) {
  let total = 0;
  let i = 0;

  // Przeliczanie rabatów dla każdego przedmiotu
  while (i < cartItems.length) {
    total += cartItems[i].price * 0.9; // 10% rabatu

    // TODO: Coś tu jest nie tak...
  }

  return total;
}

